// Scotcha service worker: makes games installable and playable offline.
// VERSION changes automatically whenever game or page files change, so players get fresh copies.
const VERSION = 'scotcha-50214763';

// Pages and files to save for offline play. This list and VERSION are regenerated by scripts/build.py
// from each game folder, so you do not need to edit them by hand.
// AUTO:precache
const PRECACHE = [
  '/',
  '/games/',
  '/404.html',
  '/about.html',
  '/manifest.webmanifest',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
  '/icons/icon-maskable-512.png',
  '/icons/apple-touch-icon.png',
  '/icons/favicon-64.png',
  '/games/rocket-dash/guide.html',
  '/games/rocket-dash/',
  '/games/rocket-dash/manifest.webmanifest',
  '/icons/rocket-dash-192.png',
  '/icons/rocket-dash-512.png',
  '/games/stack-up/guide.html',
  '/games/stack-up/',
  '/games/stack-up/manifest.webmanifest',
  '/icons/stack-up-192.png',
  '/icons/stack-up-512.png',
  '/games/volleyball-duel/guide.html',
  '/games/volleyball-duel/',
  '/games/volleyball-duel/manifest.webmanifest',
  '/icons/volleyball-duel-192.png',
  '/icons/volleyball-duel-512.png',
  '/games/word-tower/guide.html',
  '/games/word-tower/',
  '/games/word-tower/manifest.webmanifest',
  '/icons/word-tower-192.png',
  '/icons/word-tower-512.png',
  '/games/hold-up/cat.png',
  '/games/hold-up/dog.png',
  '/games/hold-up/guide.html',
  '/games/hold-up/hero.png',
  '/games/hold-up/',
  '/games/hold-up/manifest.webmanifest',
  '/games/hold-up/pilot.png',
  '/games/hold-up/santa-bloop.png',
  '/games/hold-up/santa-dog.png',
  '/icons/hold-up-192.png',
  '/icons/hold-up-512.png',
  '/games/sling-four/guide.html',
  '/games/sling-four/',
  '/games/sling-four/manifest.webmanifest',
  '/icons/sling-four-192.png',
  '/icons/sling-four-512.png'
];
// /AUTO:precache

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(VERSION)
      .then(cache => Promise.allSettled(PRECACHE.map(url => cache.add(new Request(url, { cache: 'reload' })))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k !== VERSION).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  // Only handle our own files. Ads, dictionary lookups and fonts always go straight to the network.
  if (url.origin !== location.origin) return;

  // Pages: try the network first so updates arrive, fall back to the saved copy offline.
  if (req.mode === 'navigate') {
    event.respondWith(
      fetch(req)
        .then(res => { const copy = res.clone(); caches.open(VERSION).then(c => c.put(req, copy)); return res; })
        .catch(() => caches.match(req).then(hit => hit || caches.match('/')))
    );
    return;
  }

  // Everything else: show the saved copy instantly, refresh it in the background.
  event.respondWith(
    caches.match(req).then(hit => {
      const refresh = fetch(req)
        .then(res => { if (res.ok) { const copy = res.clone(); caches.open(VERSION).then(c => c.put(req, copy)); } return res; })
        .catch(() => hit);
      return hit || refresh;
    })
  );
});
